function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'SubrectangleQueries' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with SubrectangleQueries(rectangle).';
  const rectangle = args[0][0];
  if (!Array.isArray(rectangle) || rectangle.length < 1 || rectangle.length > 100) return 'rectangle needs 1 to 100 rows.';
  const rows = rectangle.length;
  const cols = Array.isArray(rectangle[0]) ? rectangle[0].length : 0;
  if (cols < 1 || cols > 100) return 'rectangle needs 1 to 100 columns.';
  for (const line of rectangle) {
    if (!Array.isArray(line) || line.length !== cols) return 'Every row of rectangle needs the same length.';
    if (line.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Grid values are whole numbers from 1 to 10^9.';
  }
  if (operations.length - 1 > 500) return 'At most 500 calls to updateSubrectangle and getValue.';
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a) || a.some(v => !Number.isInteger(v))) return 'Each call needs whole-number arguments.';
    if (operations[i] === 'updateSubrectangle') {
      if (a.length !== 5) return 'updateSubrectangle takes row1, col1, row2, col2 and newValue.';
      const [row1, col1, row2, col2, newValue] = a;
      if (row1 < 0 || row1 > row2 || row2 >= rows) return 'Need 0 <= row1 <= row2 < rows.';
      if (col1 < 0 || col1 > col2 || col2 >= cols) return 'Need 0 <= col1 <= col2 < cols.';
      if (newValue < 1 || newValue > 1000000000) return 'newValue is between 1 and 10^9.';
    } else if (operations[i] === 'getValue') {
      if (a.length !== 2) return 'getValue takes row and col.';
      if (a[0] < 0 || a[0] >= rows || a[1] < 0 || a[1] >= cols) return 'getValue needs a cell inside the grid.';
    } else {
      return 'Only updateSubrectangle and getValue can follow the constructor.';
    }
  }
  return null;
}

