class SubrectangleQueries {
  constructor(rectangle) {
    this.original = rectangle.map(line => line.slice());
    this.updates = [];
  }
  updateSubrectangle(row1, col1, row2, col2, newValue) {
    this.updates.push([row1, col1, row2, col2, newValue]);
  }
  getValue(row, col) {
    for (let i = this.updates.length - 1; i >= 0; i--) {
      const [r1, c1, r2, c2, value] = this.updates[i];
      if (r1 <= row && row <= r2 && c1 <= col && col <= c2) return value;
    }
    return this.original[row][col];
  }
}

