function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const rows = large ? (rand() < 0.5 ? 100 : int(1, 100)) : int(1, 4);
  const cols = large ? (rand() < 0.5 ? 100 : int(1, 100)) : int(1, 4);
  const maxValue = rand() < 0.5 ? 9 : 1000000000;
  const rectangle = Array.from({ length: rows }, () => Array.from({ length: cols }, () => int(1, maxValue)));
  const calls = large ? 499 : int(1, 12);
  const updateRate = 0.2 + rand() * 0.5;
  const operations = ['SubrectangleQueries'];
  const args = [[rectangle]];
  for (let i = 0; i < calls; i++) {
    if (rand() < updateRate) {
      const a = int(0, rows - 1), b = int(0, rows - 1), c = int(0, cols - 1), d = int(0, cols - 1);
      operations.push('updateSubrectangle');
      args.push([Math.min(a, b), Math.min(c, d), Math.max(a, b), Math.max(c, d), int(1, maxValue)]);
    } else {
      operations.push('getValue');
      args.push([int(0, rows - 1), int(0, cols - 1)]);
    }
  }
  return [operations, args];
}
